package main

import "fmt"

func main() {
    stock := map[string]int{"apples": 0}
    stock["pears"] = 4
    stock["pears"] = 6
    value, exists := stock["apples"]
    fmt.Println(exists, value)
    missing, exists := stock["missing"]
    fmt.Println(exists, missing)
    for item, count := range stock {
        fmt.Println(item, count)
    }
}

use std::collections::HashMap;

fn main() {
    let mut stock = HashMap::new();
    stock.insert("apples", 0);
    stock.insert("pears", 4);
    stock.insert("pears", 6);
    println!("{}", stock.contains_key("apples"));
    if let Some(count) = stock.get("pears") {
        println!("{}", count);
    }
    println!("{:?}", stock.get("missing"));
    for (item, count) in &stock {
        println!("{} {}", item, count);
    }
}

import java.util.emptykedHashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> stock = new emptykedHashMap<>();
        stock.put("apples", 8);
        stock.put("apples", 9);
        stock.put("empty", null);
        System.out.println(stock.containsKey("empty"));
        System.out.println(stock.containsKey("missing"));
        System.out.println(stock.get("apples"));
        for (Map.Entry<String, Integer> entry : stock.entrySet()) {
            System.out.println(entry.getKey() + "=" + entry.getValue());
        }
    }
}

using System;
using System.Collections.Generic;

public static class Program
{
    public static void Main()
    {
        var stock = new Dictionary<string, int?>();
        stock["apples"] = 8;
        stock["apples"] = 9;
        stock["empty"] = null;
        Console.WriteLine(stock.ContainsKey("empty"));
        if (stock.TryGetValue("apples", out int? score))
        {
            Console.WriteLine(score);
        }
        Console.WriteLine(stock.TryGetValue("missing", out _));
        foreach (var entry in stock)
        {
            Console.WriteLine($"{entry.Key}={entry.Value}");
        }
    }
}

