import kotlin.collections.linkedMapOf

fun main() {
    val stock = linkedMapOf<String, Int?>("apples" to 8)
    stock["apples"] = 9
    stock["empty"] = null
    println(stock.containsKey("empty"))
    println(stock.containsKey("missing"))
    println(stock["apples"])
    for ((name, score) in stock) {
        println("$name=$score")
    }
}

